        print(field, "ERROR:", r["errors"][0]["message"])
    else:
        nodes = r["data"]["cycle"]["issues"]["nodes"]
        print(field, "OK, count:", len(nodes))
        if field == "identifier":
            print("   sample:", nodes[:5])
EOF

